// План specs/job-assignment.md 2.3 / 2.4 (#c9f0f5, коммит d5e3a0d). PROD, admin, компания «test», десктоп Chrome, EN.
// @writes @data: назначает/снимает QA-Tech Alpha (без согласия на SMS) на «QA-AUTO 04d33a job»; в конце — без техника.
// Источник: «מה רצוי» — предупреждение о несохранённых изменениях показывается только когда они реально есть; после выхода из страницы работы оно отменено.
// 2.3 — назначить/снять техника → Jobs через меню → перезагрузка: диалога beforeunload нет (факты 17.11: 6/6).
// 2.4 — контроль: реальная несохранённая правка описания работы → перезагрузка → диалог есть (факты 17.11: диалог есть). Правка НЕ сохраняется
//       (диалог принимается = уход со страницы, описание остаётся прежним — проверяется).
import { test, expect, Page } from '@playwright/test';
import { ADMIN_STATE, prepare, readMultiTech } from '../multi-tech-assignment/multi-tech-helpers';
import { ALPHA, acceptLeaveDialogs, assignTech, ensureNoTechnician, expectLatestHistory, openQaJob, takeOffButton } from './assignment-helpers';

test.use({ storageState: ADMIN_STATE });

/** Считает beforeunload-диалоги и принимает их (иначе перезагрузка зависнет). */
function countBeforeUnload(page: Page): { count: () => number } {
  let n = 0;
  page.on('dialog', (d) => { if (d.type() === 'beforeunload') n++; d.accept().catch(() => {}); });
  return { count: () => n };
}

test.describe('"Leave site? Changes may not be saved" only when something is really unsaved (#c9f0f5)', () => {
  test('Assign / take off a technician → Jobs via the menu → reload: no beforeunload dialog (x2) #c9f0f5 @desktop @writes @data', async ({ page }) => {
    test.setTimeout(180_000);
    await prepare(page, 'en');
    test.skip(await readMultiTech(page), '«Allow Multiple Techs» = ON — сценарий для OFF');
    acceptLeaveDialogs(page); // подготовка/очистка
    const { url } = await openQaJob(page);
    try {
      await page.goto(url);
      await ensureNoTechnician(page);

      for (const action of ['assign', 'take-off'] as const) {
        await page.goto(url);
        if (action === 'assign') {
          await assignTech(page, ALPHA);
          await expectLatestHistory(page, `Assigned to ${ALPHA}`);
        } else {
          await takeOffButton(page, ALPHA).click();
        }
        await page.getByRole('link', { name: 'Jobs', exact: true }).filter({ visible: true }).first().click();
        await page.waitForURL(/\/jobs/i);

        page.removeAllListeners('dialog');
        const seen = countBeforeUnload(page);
        await page.reload();
        await expect(page.getByPlaceholder(/^Search jobs/i)).toBeVisible({ timeout: 30_000 });
        expect(seen.count(), `после «${action}» и ухода на Jobs диалога «Leave site?» нет`).toBe(0);
        page.removeAllListeners('dialog');
        acceptLeaveDialogs(page);
      }
    } finally {
      await page.goto(url).catch(() => {});
      await ensureNoTechnician(page).catch(() => {});
    }
  });

  test('Control: a real unsaved edit on the job page still triggers the beforeunload dialog #c9f0f5 @desktop @writes @data', async ({ page }) => {
    test.setTimeout(120_000);
    await prepare(page, 'en');
    acceptLeaveDialogs(page);
    const { url } = await openQaJob(page);
    await page.goto(url);
    const desc = page.getByLabel('Job Description');
    await expect(desc).toBeVisible({ timeout: 30_000 });
    const before = await desc.inputValue();
    await desc.click();
    await desc.press('End');
    await desc.pressSequentially(' unsaved');

    page.removeAllListeners('dialog');
    const seen = countBeforeUnload(page);
    await page.reload();
    await expect.poll(() => seen.count(), { message: 'при несохранённой правке диалог «Leave site?» показан', timeout: 15_000 }).toBeGreaterThan(0);
    await expect(page.getByLabel('Job Description'), 'правка не сохранилась').toHaveValue(before, { timeout: 30_000 });
  });
});
